const j=$input.first().json;
if(!Array.isArray(j.characters)||!j.characters.length) throw new Error('characters must be a non-empty array');
const per=Number(j.ads_per_character); if(!Number.isInteger(per)||per<1||per>20) throw new Error('ads_per_character must be 1..20 for this run');
const out=[]; for(const c of j.characters){ if(!c.character_id||!c.ad_concept) throw new Error('each character requires character_id and ad_concept'); for(let i=0;i<per;i++) out.push({json:{character_id:String(c.character_id),concept:String(c.ad_concept),variation:i+1,source_tool:'unnamed custom connector (not supplied)',generation:'MANUAL_HANDOFF',review_status:'needs_human_review',publish_status:'disabled',source_claims_unverified:true}}); }
return out;
